-- Backfill per-entity SEO copy into existing content rows.
-- Non-destructive: JSONB-merges a "seo" key; skips any row that already has one.
-- Safe to run more than once. Run AFTER deploying the code that reads seo.
-- Tools are static (no DB) and need no backfill.

-- services: 6 rows
update public.services set data = data || '{"seo":{"title":"SEO & Organic Growth Services","description":"Own your category in search and in AI answers with topic clusters, programmatic SEO, and an answer-first content system built to compound for years."}}'::jsonb where slug = 'seo' and not (data ? 'seo');
