update public.services set data = data || '{"seo":{"title":"Content Strategy & Editorial Systems","description":"An editorial engine that demonstrates real thinking: content pillars, a repurposing pipeline, and a QA rubric that turns one idea into a month of distribution."}}'::jsonb where slug = 'content' and not (data ? 'seo');
update public.services set data = data || '{"seo":{"title":"AI Automation & Workflows","description":"Custom AI workflows for research, drafting, analysis, and ops — built with human-in-the-loop QA gates so quality goes up, not down, as output scales."}}'::jsonb where slug = 'ai-workflows' and not (data ? 'seo');
update public.services set data = data || '{"seo":{"title":"Startup Advisory for Founders","description":"Founder-to-founder advisory on growth, distribution, and positioning — hands-on working sessions built for early and growth-stage startups."}}'::jsonb where slug = 'advisory' and not (data ? 'seo');
update public.services set data = data || '{"seo":{"title":"SEO & AI Speaking, Workshops","description":"Keynotes and workshops on SEO, AI workflows, and founder-led growth — built on real experiments and outcomes, not recycled theory or borrowed slides."}}'::jsonb where slug = 'speaking' and not (data ? 'seo');

